import{_ as t,H as i,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"开篇词：个人发展的底层逻辑","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是个人发展","slug":"什么是个人发展","link":"#什么是个人发展","children":[]},{"level":2,"title":"个体发展双螺旋模型","slug":"个体发展双螺旋模型","link":"#个体发展双螺旋模型","children":[]},{"level":2,"title":"团队效能动力模型","slug":"团队效能动力模型","link":"#团队效能动力模型","children":[]},{"level":2,"title":"职业发展没有捷径","slug":"职业发展没有捷径","link":"#职业发展没有捷径","children":[]}],"relativePath":"工程师个人发展指南/开篇词：个人发展的底层逻辑.md","filePath":"工程师个人发展指南/开篇词：个人发展的底层逻辑.md","lastUpdated":1795556167000}'),l={name:"工程师个人发展指南/开篇词：个人发展的底层逻辑.md"};function n(s,e,E,r,o,h){return i(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="开篇词-个人发展的底层逻辑" tabindex="-1">开篇词：个人发展的底层逻辑 <a class="header-anchor" href="#开篇词-个人发展的底层逻辑" aria-label="Permalink to &quot;开篇词：个人发展的底层逻辑&quot;">​</a></h1><p>你好，我是李云，很高兴能在极客时间，和你聊聊工程师的个人发展。</p><p>我猜与“个人发展”这个词相比，你更常听到和更关注的是“职业发展”这四个字。也是，我们踏入社会谋生，是先从职业发展中来解决个人的生存问题的，然后才考虑发展问题。</p><p>面对自己的职业发展，我想你和我一样，曾经面临或将会面临以下这些问题吧。</p><ol><li><p>如何跨越“35 岁年龄焦虑”？</p></li><li><p>怎样成长为一名技术专家，要怎么学，又要学什么呢？</p></li><li><p>我适合成为技术管理者吗，又要为那天的到来在平时做怎样的准备呢？</p></li><li><p>面对人工智能这类新技术的出现，要如何应对来确保自己的职业安全呢？</p></li></ol><p>这些问题，关乎个人职业技能的发展，和职位、职级、职业声望的提升，是职业发展更具体的内容。你可能会问了，一门针对工程师的课，为什么用的是“个人发展”这个词，而不是“职业发展”？</p><h2 id="什么是个人发展" tabindex="-1">什么是个人发展 <a class="header-anchor" href="#什么是个人发展" aria-label="Permalink to &quot;什么是个人发展&quot;">​</a></h2><p>那咱们再一起想想，除了上面这些问题，我们在工作中是不是也会经历下面这些困惑。</p><ol><li><p>如何与自己的主管相处？</p></li><li><p>怎样更健康地面对工作压力？</p></li><li><p>如何减少和解决工作环境给自己带来的精神内耗？</p></li><li><p>在冲突、越级汇报、述职汇报等关键沟通中，要注意什么？</p></li></ol><p>这些问题，关乎个人的心理弹韧性、心智模式、情绪管理、关系管理和爱好的发展，我把它们归类于个人的自我发展课题中。个人的自我发展得如何，除了影响自己在职场上的表现外，还会影响生活层面的。是的，我们每个人都得同时扮演好在职场和生活中的不同角色，工作中我们面对的是同事、上司和下属，生活中与我们互动的是配偶、孩子和父母。</p><p>基于这样的理解，我总结了一个公式：个人发展 = 职业发展 + 自我发展。</p><p>如果你关注的焦点更多是在职业发展上，没有特别有意识地关注和学习过自我发展方面的内容的话，你可能会好奇：为什么这门针对职场人士的课，要如此强调个人的自我发展？</p><h2 id="个体发展双螺旋模型" tabindex="-1">个体发展双螺旋模型 <a class="header-anchor" href="#个体发展双螺旋模型" aria-label="Permalink to &quot;个体发展双螺旋模型&quot;">​</a></h2><p>拿我自己来说吧。从职业发展的角度，大学毕业后，我有了短暂的两年电气与电子硬件开发工作经历后，因为对软件开发的兴趣，通过自学于 1999 年踏上了软件开发工程师的职业道路。后来有近 4 年在电力行业；近 10 年在通信行业，曾是摩托罗拉的系统架构师；近 10 年在互联网行业一直就职于阿里巴巴，是一名高级技术专家；1 年芯片行业担任教育版块的高管。在阿里巴巴工作期间，完成了从一名技术人向技术管理人的角色转变，这才有了后面担任高管的经历。</p><p>从生活角度，我有两个女儿，大女儿 2023 年下半年进入大学就读，同期小女儿就读小学四年级。换句话说，我完整地经历了大女儿的养育周期，最深刻的体会如果用一句话表达，那就是“育儿就是育己”。整个过程走下来，我最初发现自己不仅对于育儿这事是无知的，对自己也是相当无知的。有了那些发现后，才有了后面开始阅读育儿和自我发展相关的书籍这事。学着学着，发现这一切都指向了自我的成长，让自己有了更好的觉察和自我改变能力，这些对于夫妻关系和亲子关系的改善都有巨大的帮助。别说我没告诉你哈，如果你有孩子或将来有了孩子，良好的夫妻关系是良好亲子关系的基础，当夫妻关系不融洽时，会让家庭在育儿上面临更大的挑战。</p><p>当然了，我的职业发展和生活是交织在一起的，生活上带来自我成长的同时，让我能更好地克服职业发展所面临的巨大挑战，因为一个内心更加充盈的自我，才能更好地应对挑战所带来的压力和焦虑。同时，自我的成熟让我在带团队时，会有更多的觉察和反思，这对于践行人性化管理相当有帮助。因为作为一名管理者，先照顾好自己才能照顾好团队。</p><p>基于自己职业和生活的经历，我发现充分发展自我的场景并非来自工作，而是来自生活。这个点也好理解，因为职场中的关系没有生活中的那么亲近，职场所产生的冲突更多是物质层面的利益，但生活中的却主要是精神层面的自我，且想避也避不开。</p><p>此外，我还发现了一些让人堪忧的现象，比如：</p><ol><li><p>个体过于投入自己的职业发展，但忽视了应承担的家庭责任，甚至造就了“丧偶式育儿”的现象。</p></li><li><p>追求职业成功的过程中，忘记了照顾好自己，想照顾自己但又不知问题究竟出在哪，不知如何下手。</p></li><li><p>有些职场人士的表现相当不成熟，过于自我但不自知。</p></li></ol><p>这些现象提醒我们应当更加重视自我的发展，但现实是很多人没有这样的意识，学校和父辈都很少传授与指点。基于这一现状，我提出了下图所示的“个体发展双螺旋模型”，这是个人发展的一个底层逻辑。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>这个模型告诉我们，自我发展与职业发展应并重，背后隐含的是物质文明和精神文明的协调发展，以及平衡好工作与生活。</p><p>也正是基于这个逻辑，咱们这门课的核心模块就是职业发展和自我发展，同时我把一些个人发展的基础命题整理出一个小模块放在课程最前面，这样咱们就能先有一些概念和理念的共识，然后再进入职业发展和自我发展具体的内容里。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" alt=""></a></p><h2 id="团队效能动力模型" tabindex="-1">团队效能动力模型 <a class="header-anchor" href="#团队效能动力模型" aria-label="Permalink to &quot;团队效能动力模型&quot;">​</a></h2><p>聊到这里，我希望你能开始重视自我发展这事儿了，它和职业发展同样重要。但是我也知道，职业发展离我们很近，有太多眼前就需要解决的问题和挑战，那我们还是花一些时间再聊聊职业发展。</p><p>个人的职业发展是一个非常宏大的命题，不仅内容丰富，时间跨度还特别长甚至超过了育儿的。如果将个人的职业发展当作是一个项目来看待的话，挑战在于它涉及到不断变化的目标、身边环境的不确定性、以及个人能力和意愿的发展。职业发展不像典型的项目那样有明确的起始点和目标，而是一个持续的过程，需要个人在职业生涯中不断地做出选择和调整。</p><p>面对如此宏大的命题，追求个人职业发展轨迹的精确性只能迎来失望的结果，取而代之更好的办法，是追求大方向的正确，换句话说我们用模糊来换取踏实与信心。问题是，怎么个模糊法？</p><p>虽说个人的特质和经历是独特的，但在职业发展的道路上所面临的问题，却有很大的共性，比如，开头提到的那些问题。不过，好些问题是“果”，需要我们着力于“因”才能防范或解决，这就得透过问题去看到更深层次的内容。如果深层次的内容是规律、规则、原则、方法论，那个人就可以基于自己的具体情况加以运用，具有很好的通用性，当然也意味着一定的模糊性。</p><p>规律、规则、原则给人的感觉好像有点小，那何时要用到比它们更大的方法论呢？这是个好问题。</p><p>纵观每位工程师的职业发展，无外乎都在“爬”下图所示的两个阶梯。换句话说，个人的发展会随着时间的推移有不同的要求。那这些要求之间有共性和连续性吗？另外，如果谈论个人的职业发展只聚焦于个人，没有团队和组织的视角，那就太局限了。别忘了，个人的职业发展是在团队和组织中完成的。那么个人的技能成长又如何与团队和组织的要求相结合呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/3.png" alt=""></a></p><p>为了回答好这两个问题，我基于自己的思考与实践，提出了下图所示的“团队效能动力模型”这一方法论。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%B8%AA%E4%BA%BA%E5%8F%91%E5%B1%95%E6%8C%87%E5%8D%97/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/4.png" alt=""></a></p><p>这个模型告诉我们，个人的职业发展需要从自我管理、知识管理、专业技能和业务技能，这四个维度来提升自己的职业素养，职级越高对这四个维度的要求也越高，背后解决的是要求的共性与连续性问题。此外，个体的职业发展是嵌入于团队效能这个大背景之下的，受工作环境影响的同时，还得改造工作环境，这就解决了个人的发展与团队、组织的关系问题。无论你是技术阶梯中的工程师，还是技术管理阶梯的管理者，这个模型都为你的发展提供了蓝图，确保职业发展连续性的同时，还将个人与团队做了有机结合。</p><h2 id="职业发展没有捷径" tabindex="-1">职业发展没有捷径 <a class="header-anchor" href="#职业发展没有捷径" aria-label="Permalink to &quot;职业发展没有捷径&quot;">​</a></h2><p>好了，今天是课程的开篇，和你分享了我总结的两个模型，一个是个体发展双螺旋模型，另一个是团队效能动力模型。这两个模型揭示了个人发展的两个底层逻辑。结合这两个模型咱们一起重新思考了个人发展这个命题。“个人发展 = 职业发展 + 自我发展”这个公式很简单，但是能够不局限在单点上，整合思考看问题会给我们带来很大改变。</p><p>在你着手学习下一讲之前，我得先叮嘱你一点，那就是个人发展没有捷径，以免你对本课程产生不切实际的预期。</p><p>是的，这门课包含了我在工作与生活中超过 25 年的部分经历、洞察和经验积累。基于我自己在职场的成长经历，在工作中所扮演过的工程师、架构师、技术经理和高管这些不同的角色，以及生活中作为两个孩子的父亲和妻子的丈夫，我认可更高质量的个人发展，是存在有效的方法和策略的，但并没有简单快速的捷径。</p><p>原因很简单，个人发展是关于个人的职业技能成长和自我成长的，除非分别走到职业和人生的终点，否则根本没有尽头，需要我们不断地学习并做出自我改变。另外，我并不赞成用“成功”和“失败”去评价一个人的发展，我们都是各自幸福的探索者，相比于用钱、地位去衡量人，我认为自我的充盈才能收获真正的幸福，当生存不是问题时，每个人都可以找到自己的幸福。</p><p>最后，期待这门课能给你带去帮助、启发。也期待你能多留言与我互动，这样你才能激发我所掌握的知识来更好地帮助你。如果有些问题我不能很好地解答，相信也会给我带来成长。所谓教学相长，咱们在互动中一定能彼此激发，一起进步。</p><p>结束前给你留个思考题吧，在学习这一讲之前，你是如何理解自我发展的呢？期待你留言与我分享交流。</p><p>让我们下一讲见。</p>',43)])])}const c=t(l,[["render",n]]);export{B as __pageData,c as default};
